///
/// @brief Apply automatic checking valid clauses
/// @note Required for directives whose clauses may be parenthesized lists (e.g., routine(name), declare target(list)); the sorting stage token-pastes clause texts and cannot handle them
/// @note The parenthesized elements come first (e.g., routine (name) seq, as OpenACC requires the name right after routine)
/// @warning More than 32 clause candidates (empty elements are not counted) stop the build:
///          - Error message: 'Solomon: too many clauses for one directive (limit 32)'
///          - To raise the limit, regenerate check_clause.jl, sort_clause.jl, dedup_wait.jl, and nest_map.jl with the same --max (README)
///
#define SOLOMON_INTERNAL_APPEND_CLAUSES_WITHOUT_SORTING(...) SOLOMON_INTERNAL_PARENS_FIRST(SOLOMON_INTERNAL_CHECK_CLAUSE_32(SOLOMON_INTERNAL_PICKUP_DRAIN_ENTRY(__VA_ARGS__)))

#endif  // !defined(SOLOMON_UTIL_IMPL_CHECK_CLAUSE_HPP)
